#include <iostream>
using namespace std;

class MaxHeap {
private:
  int *heap;
  int capacity;
  int size;

void maxHeapify(int index) {
    int left = 2 * index + 1;
    int right = 2 * index + 2;
    int largest = index;
    if (left < size && heap[left] > heap[largest]) {
        largest = left;
    }
    if (right < size && heap[right] > heap[largest]) {
        largest = right;
    }
    if (largest != index) {
        int temp = heap[index];
        heap[index] = heap[largest];
        heap[largest] = temp;
        maxHeapify(largest);
    }
}

public:
    MaxHeap(int max_size) {
        capacity = max_size;
        heap = new int[capacity];
        size = 0;
    }
    ~MaxHeap() {
        delete[] heap;
    }
    void insert(int value) {
        if (size == capacity) {
        cout << "Heap is full. Cannot insert more elements.\n";
        return;
    }
    int index = size;
    heap[index] = value;
    size++;

    while (index > 0 && heap[index] > heap[(index - 1) / 2]) {
      int temp = heap[index];
      heap[index] = heap[(index - 1) / 2];
      heap[(index - 1) / 2] = temp;
      index = (index - 1) / 2;
    }
  }
void printHeap() {
    cout << "Max-Heap: ";
    for (int i = 0; i < size; i++) {
        cout << heap[i] << " ";
    }
    cout << endl;
}
};

int main() {
    MaxHeap maxHeap(10);
    int nums[] = {10, 20, 15, 7, 9, 30, 25};
    for (int i = 0; i < 8; i++) {
        maxHeap.insert(nums[i]);
    }
    maxHeap.printHeap();
    return 0;
}

